            const price = Number(row && row.buyPrice);
            const from = Number(row && row.bulkThreshold);
            const each = Number(row && row.bulkBuyPrice);
            if (!Number.isInteger(itemId) || itemId <= 0 || !Number.isFinite(price) || price <= 0) continue;
